import { test, expect } from '@playwright/test';

test.describe('Form Submission Error Auto-Scroll', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should automatically scroll to form submission errors when validation fails', async ({ page }) => {
    // Intercept the form submission API
    await page.route('**/api/submit-form', (route) => {
      route.abort('blockedbyclient');
    });

    // Fill form with invalid data
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('short');

    // Click submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for error message to appear
    await page.waitForTimeout(500);

    // Verify error messages are visible
    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).toBeVisible();

    const passwordError = page.getByText('Password must be at least 8 characters');
    await expect(passwordError).toBeVisible();

    // Verify the page has scrolled to the error messages
    const emailErrorBox = page.locator('[data-testid="email-error-box"]');
    await expect(emailErrorBox).toBeVisible();

    const scrollPosition = await page.evaluate(() => window.scrollY);
    expect(scrollPosition).toBeGreaterThan(0);

    // Verify the error container is in the viewport
    const errorContainer = page.locator('[data-testid="form-error-container"]');
    const isErrorContainerInViewport = await errorContainer.evaluate((el) =>
      el.getBoundingClientRect().top >= 0 &&
      el.getBoundingClientRect().bottom <= (window.innerHeight || document.documentElement.clientHeight)
    );
    expect(isErrorContainerInViewport).toBe(true);
  });

  test('should not scroll when form submission is successful', async ({ page }) => {
    // Intercept the form submission API and return success
    await page.route('**/api/submit-form', (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ success: true, message: 'Form submitted successfully' }),
      });
    });

    // Fill form with valid data
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('Jane Smith');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('jane@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('ValidPassword123');

    // Click submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for success response
    await page.waitForTimeout(500);

    // Verify success message is displayed
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify no error messages are visible
    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).not.toBeVisible();

    const passwordError = page.getByText('Password must be at least 8 characters');
    await expect(passwordError).not.toBeVisible();

    // Verify the page has not scrolled to error messages
    const scrollPosition = await page.evaluate(() => window.scrollY);
    expect(scrollPosition).toBeLessThan(10);
  });
});
